/* ================= JEE Main physics (Premium) =================
   JEE Main Paper 1 physics: 25 questions = Section A, 20 multiple choice + Section B, 5 numerical-value
   answers (all compulsory). +4 correct, −1 wrong, 0 unanswered. Units follow the NTA syllabus (20 units),
   each mapped to the NCERT Class 11 and 12 chapters in PhysiQuest. g = 10 m/s² in JEE-style questions. */
const JEE_FACTS='In JEE Main Paper 1, Physics has 25 questions: 20 multiple-choice (Section A) and 5 with a numerical answer (Section B), all compulsory. Each is +4 if correct and −1 if wrong; an unanswered question is 0. Physics is 100 of the 300 marks in the 3-hour paper.';
const JEE=[
 {u:1,t:'Units and Measurements',ch:[[11,1]],f:['Dimensions check an answer in seconds, and can find it when the quantity is a product of powers.','Maximum % error in aᵖbᵠ/cʳ is p(%a) + q(%b) + r(%c): errors always add, even in the denominator.','Round only at the end; keep one extra significant figure while you work.']},
 {u:2,t:'Kinematics',ch:[[11,2],[11,3]],f:['For variable acceleration, differentiate x(t) for v and a; use a = v dv/dx when a depends on x.','Thrown up from a height: take up as positive and solve −h = ut − ½gt² for the positive root.','River crossing: shortest time means heading straight across; shortest path means the resultant points straight across.']},
 {u:3,t:'Laws of Motion',ch:[[11,4]],f:['For connected bodies, write F = ma for each body, then add the equations to remove the tension.','In an accelerating frame add a pseudo force −ma (lifts, accelerating wedges).','On a 37° incline use sin 37° = 3/5 and cos 37° = 4/5: JEE uses this angle often.']},
 {u:4,t:'Work, Energy and Power',ch:[[11,5]],f:['The work–energy theorem counts the work of every force: friction and springs included.','Vertical circle on a string: least speed √(5gR) at the bottom and √(gR) at the top.','Perfectly inelastic collision: the fraction of KE lost is m₂/(m₁ + m₂) when m₂ is at rest.']},
 {u:5,t:'Rotational Motion',ch:[[11,6]],f:['Parallel axis: I = I_cm + Md². Perpendicular axis (flat bodies only): I_z = I_x + I_y.','Rolling without slipping: v = ωR and KE = ½mv²(1 + k²/R²).','Angular momentum about a point is conserved when the net external torque about that point is zero.']},
 {u:6,t:'Gravitation',ch:[[11,7]],f:['Inside a uniform sphere g ∝ r; outside g ∝ 1/r².','A satellite in a circular orbit: E = −GMm/2r, KE = −E and PE = 2E.','Kepler’s third law T² ∝ r³ links any two orbits around the same body.']},
 {u:7,t:'Properties of Solids and Liquids',ch:[[11,8],[11,9],[11,10]],f:['Terminal speed ∝ r²: when n drops merge, r grows by n^(1/3), so the speed grows by n^(2/3).','Excess pressure is 2T/r in a drop and 4T/r in a soap bubble, which has two surfaces.','Ice in water: first check whether the water can melt all the ice, then find the final temperature.']},
 {u:8,t:'Thermodynamics',ch:[[11,11]],f:['Work is the area under the p–V curve; the area inside a cycle is the net work.','Adiabatic: pV^γ and TV^(γ−1) stay constant; γ = 5/3 monatomic, 7/5 diatomic.','Carnot refrigerator: COP = T₂/(T₁ − T₂), always in kelvin.']},
 {u:9,t:'Kinetic Theory of Gases',ch:[[11,12]],f:['v_rms = √(3RT/M) > v_avg = √(8RT/πM) > v_mp = √(2RT/M).','For a mixture, add heat capacities mole by mole: C_v = Σn·C_v ÷ Σn.','Mean free path λ = 1/(√2 π d² n): bigger or more crowded molecules travel less far.']},
 {u:10,t:'Oscillations and Waves',ch:[[11,13],[11,14]],f:['In SHM v = ω√(A² − x²); KE and PE trade places but ½kA² stays fixed.','Cut a spring into n equal parts and each part is n times stiffer.','Doppler: f′ = f(v ± v_o)/(v ∓ v_s), with the upper signs when source and observer approach.']},
 {u:11,t:'Electrostatics',ch:[[12,1],[12,2]],f:['Dielectric with the battery connected: V stays fixed. Disconnected first: Q stays fixed.','Flux through a closed surface depends only on the charge inside, not on the shape.','Between two like charges, the field is zero at a point closer to the smaller charge.']},
 {u:12,t:'Current Electricity',ch:[[12,3]],f:['Stretch a wire n times (same volume) and R becomes n²R; shrink its radius to 1/n and R becomes n⁴R.','A cell gives its largest power ε²/4r to a load equal to its internal resistance.','Metre bridge: R/S = l/(100 − l), with l measured from the end where R is connected.']},
 {u:13,t:'Magnetic Effects of Current and Magnetism',ch:[[12,4],[12,5]],f:['r = mv/qB = √(2mK)/qB = √(2mqV)/qB: use the form that matches the data.','Rewind a fixed length of wire into n turns and the field at the centre becomes n² times larger.','Parallel currents in the same direction attract: F/L = μ₀I₁I₂/(2πd).']},
 {u:14,t:'Electromagnetic Induction and Alternating Currents',ch:[[12,6],[12,7]],f:['A rod of length L spinning about one end in field B: ε = ½BωL².','At resonance in series LCR, Z = R, the current is largest and the power factor is 1.','Average power = V_rms I_rms cos φ: a pure inductor or capacitor uses none.']},
 {u:15,t:'Electromagnetic Waves',ch:[[12,8]],f:['E₀ = cB₀, and the wave travels along E × B.','The average energy is shared equally between the electric and magnetic fields.','Displacement current ε₀ dΦ_E/dt keeps Ampère’s law true inside a charging capacitor.']},
 {u:16,t:'Optics',ch:[[12,9],[12,10]],f:['A lens in a liquid: 1/f ∝ (n_lens/n_liquid − 1). Equal indices make the lens vanish.','A film of index μ and thickness t over one slit shifts the YDSE pattern by (μ − 1)t/λ fringes, towards that slit.','Telescope in normal adjustment: m = f_o/f_e and tube length f_o + f_e.']},
 {u:17,t:'Dual Nature of Matter and Radiation',ch:[[12,11]],f:['eV₀ = hc/λ − φ. A graph of V₀ against f has slope h/e.','λ = h/p = h/√(2mK) = h/√(2mqV) for a charge accelerated through V.','Intensity sets the photocurrent; frequency sets the stopping potential.']},
 {u:18,t:'Atoms and Nuclei',ch:[[12,12],[12,13]],f:['Hydrogen-like ions: E_n = −13.6 Z²/n² eV and r_n = 0.529 n²/Z Å.','From level n, an atom can give n(n − 1)/2 different spectral lines.','N = N₀(½)^(t/T½); mean life τ = T½/0.693 ≈ 1.44 T½.']},
 {u:19,t:'Electronic Devices',ch:[[12,14]],f:['Ideal diode: a short circuit forward, an open switch in reverse. A silicon diode drops about 0.7 V.','Zener regulator: the series-resistor current splits into the Zener current and the load current.','NAND and NOR are universal gates: learn NOT, AND and OR built from each.']},
 {u:20,t:'Experimental Skills',ch:[[11,1]],f:['Vernier least count = 1 MSD − 1 VSD; 10 VSD = 9 MSD of 1 mm gives 0.1 mm.','Screw gauge: subtract a positive zero error and add a negative one.','From a T²–L graph of a pendulum, g = 4π² ÷ slope.']}
];

/* ---------- JEE question templates ----------
   J() makes an item: prompt, hint, right value, unit, worked solution, and wrong values with the mistake behind
   each. An item becomes a Section A question (four options) or, when its value is a whole number, a Section B
   question (type the number). JP() gives fixed conceptual questions, Section A only. */
const JGEN={};
function J(p,h,v,u,why,wr,o){return Object.assign({p,h,v,u:u||'',why,wr:wr||[]},o||{});}
const isWhole=v=>isFinite(v)&&Math.abs(v)>=1&&Math.abs(v)<1e7&&Math.abs(v-Math.round(v))<1e-6;
const nn=x=>isWhole(x)?String(Math.round(x)).replace('-','−'):nf(x);
function wholeOf(f){let it=null;for(let i=0;i<60;i++){it=f();if(it&&isWhole(it.v))return it;}return it;}
const JP=list=>()=>{const q=rp(list);return{mc:MC(q[0],q[1],[q[2],q[3]],q[4])};};
/* “a 5 V …” but “an 8 V …”, “an 11 …”, “an 18 …” */
const aN=(x,cap)=>{const t=String(x),an=t[0]==='8'||/^1[18](\D|$)/.test(t);return (cap?(an?'An':'A'):(an?'an':'a'))+' '+t;};
const mn=x=>String(x).replace('-','−');

